// Title: Generate HTML from an Aspose.Cells workbook and inject a :root CSS variable using C#
// Common Searches: C# add a CSS variable to HTML output generated by Aspose.Cells | how to insert a :root selector into Aspose.Cells exported HTML file | modify Aspose.Cells HTML export to include custom property '--primary-color' with .NET | ensure CSS custom property exists in workbook HTML saved by Aspose.Cells | use regex to update style block in Aspose.Cells HTML export in C#
// Tags: Aspose.Cells HTML export custom CSS variable | C# inject :root selector into generated HTML | regex modify style block in Aspose.Cells output | add CSS custom property to workbook HTML | ensure CSS variable in Aspose.Cells HTML file

using System;
using System.IO;
using System.Text;
using System.Text.RegularExpressions;
using Aspose.Cells;

namespace AsposeCellsHtmlCssDemo
{
    // The example creates a simple workbook, saves it as HTML with Aspose.Cells, reads the resulting file, checks for a <style> block containing a :root selector, inserts the '--primary-color' custom property if missing, adds a new <style> element when needed, and writes the updated HTML back to disk.
    class Program
    {
        static void Main(string[] args)
        {
            // Path for the generated HTML file
            const string htmlPath = "workbook.html";

            // CSS custom property to ensure
            const string rootSelector = ":root";
            const string customProperty = "--primary-color";
            const string customValue = "#4A90E2";

            try
            {
                // 1. Create a simple workbook with some data
                var workbook = new Workbook();
                var sheet = workbook.Worksheets[0];
                sheet.Cells["A1"].PutValue("Name");
                sheet.Cells["B1"].PutValue("Score");
                sheet.Cells["A2"].PutValue("Alice");
                sheet.Cells["B2"].PutValue(85);
                sheet.Cells["A3"].PutValue("Bob");
                sheet.Cells["B3"].PutValue(92);

                // 2. Export the workbook to HTML
                workbook.Save(htmlPath, SaveFormat.Html);

                // Ensure the HTML file was created
                if (!File.Exists(htmlPath))
                {
                    Console.WriteLine($"Error: HTML file '{htmlPath}' was not created.");
                    return;
                }

                // 3. Load the generated HTML as text
                string htmlContent = File.ReadAllText(htmlPath);

                // 4. Ensure there is a <style> element that contains a :root selector
                //    with the required CSS custom property.
                bool rootExists = false;
                bool propertyExists = false;

                // Regex to find <style> blocks
                var styleRegex = new Regex(@"<style[^>]*>(.*?)</style>", RegexOptions.Singleline | RegexOptions.IgnoreCase);
                var matches = styleRegex.Matches(htmlContent);

                foreach (Match match in matches)
                {
                    string styleBlock = match.Groups[1].Value;

                    if (styleBlock.Contains(rootSelector))
                    {
                        rootExists = true;
                        if (styleBlock.Contains(customProperty))
                        {
                            propertyExists = true;
                        }
                        else
                        {
                            // Insert the custom property inside the existing :root block
                            // Find the opening brace of :root
                            int rootIndex = styleBlock.IndexOf(rootSelector, StringComparison.Ordinal);
                            int braceOpen = styleBlock.IndexOf('{', rootIndex);
                            if (braceOpen != -1)
                            {
                                // Insert after the opening brace
                                var sb = new StringBuilder(styleBlock);
                                sb.Insert(braceOpen + 1, $" {customProperty}: {customValue};");
                                string newStyleBlock = sb.ToString();

                                // Replace the old style block in the HTML
                                htmlContent = htmlContent.Replace(styleBlock, newStyleBlock);
                            }
                        }
                        break; // No need to examine further style blocks
                    }
                }

                // 5. If no :root selector was found, create a new <style> element with it
                if (!rootExists)
                {
                    string newStyleTag = $"<style>{rootSelector} {{ {customProperty}: {customValue}; }}</style>";

                    // Try to insert into <head> if present
                    var headRegex = new Regex(@"<head[^>]*>", RegexOptions.IgnoreCase);
                    var headMatch = headRegex.Match(htmlContent);
                    if (headMatch.Success)
                    {
                        // Insert after the opening <head> tag
                        int insertPos = headMatch.Index + headMatch.Length;
                        htmlContent = htmlContent.Insert(insertPos, newStyleTag);
                    }
                    else
                    {
                        // No <head> tag; prepend the style tag at the beginning of the document
                        htmlContent = newStyleTag + Environment.NewLine + htmlContent;
                    }
                }

                // 6. Save the modified HTML back to disk
                File.WriteAllText(htmlPath, htmlContent, Encoding.UTF8);

                Console.WriteLine($"HTML file '{htmlPath}' has been processed and ensured to contain the required CSS custom property.");
            }
            catch (Exception ex)
            {
                Console.WriteLine($"An error occurred: {ex.Message}");
            }
        }
    }
}
